-- -----------------------------------
-- Table structure for `network_report_list`
-- -----------------------------------

DROP TABLE IF EXISTS `network_report_list`;
CREATE TABLE `network_report_list` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `Customer` varchar(25) CHARACTER SET utf8mb4 NOT NULL,
  `Bank` varchar(13) CHARACTER SET utf8mb4 NOT NULL,
  `SN` int(11) NOT NULL,
  `ATMID` varchar(40) CHARACTER SET utf8mb4 NOT NULL,
  `SiteAddress` text CHARACTER SET utf8mb4,
  `router_status` int(11) DEFAULT '0',
  `router_ip` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL,
  `router_lastcommunication` varchar(120) CHARACTER SET utf8mb4 DEFAULT NULL,
  `router_online_count` int(11) NOT NULL DEFAULT '0',
  `router_offline_count` int(11) NOT NULL DEFAULT '0',
  `router_tot_count` int(11) NOT NULL DEFAULT '0',
  `router_online_percent` float DEFAULT NULL,
  `dvr_status` int(11) DEFAULT '0',
  `dvr_ip` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL,
  `dvr_lastcommunication` varchar(120) CHARACTER SET utf8mb4 DEFAULT NULL,
  `dvr_online_count` int(11) NOT NULL DEFAULT '0',
  `dvr_offline_count` int(11) NOT NULL DEFAULT '0',
  `dvr_tot_count` int(11) NOT NULL DEFAULT '0',
  `dvr_online_percent` float DEFAULT NULL,
  `panel_status` int(11) DEFAULT '0',
  `panel_ip` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL,
  `panel_lastcommunication` varchar(120) CHARACTER SET utf8mb4 DEFAULT NULL,
  `panel_online_count` int(11) NOT NULL DEFAULT '0',
  `panel_offline_count` int(11) NOT NULL DEFAULT '0',
  `panel_tot_count` int(11) NOT NULL DEFAULT '0',
  `panel_online_percent` float DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `last_action_date` date NOT NULL DEFAULT '2022-07-25',
  `live` char(1) CHARACTER SET utf8mb4 NOT NULL,
  `is_update` tinyint(4) NOT NULL DEFAULT '0',
  `today_tot_hit` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=7072 DEFAULT CHARSET=latin1;

